'use strict';

/**
* Xorshift128+ pseudorandom number generator (default instance).
*
* @module @stdlib/random/base/xorshift128
* @type {Function}
* @returns {number} pseudorandom 32-bit unsigned integer
*
* @example
* var rng = require( '@stdlib/random/base/xorshift128' );
*
* var v = rng();
* // returns <function>
*
* var n = rng.normalized();
* // throws <TypeError>
*/

// MODULES //

var factory = require( './factory.js' );
var randi32 = require( './rand_int32.js' );


// MAIN //

/**
* Default Xorshift128+ PRNG instance.
*
* @type {Function}
* @returns {number} pseudorandom 32-bit unsigned integer
*/
var xorshift128plus = factory({
	'seed': randi32()
});


// EXPORTS //

module.exports = xorshift128plus;
